#include <vector>
#include <unordered_map>

using namespace std;

class Solution {
public:
    bool canArrange(vector<int>& arr, int k) {
        unordered_map<int, int> count;
        for (int num : arr) {
            int r = ((num % k) + k) % k;
            count[r]++;
        }

        if (count[0] % 2 != 0) return false;
        for (int i = 1; i < k; ++i)
            if (count[i] != count[k - i]) return false;

        return true;
    }
};
